      "section": "B1",
      "lyrics": [
        "笑ったり悩んでみたり",
        "この広い世界のすみっこで",
        "僕らでうちゅうのふしぎ",
        "解き明かしてみよう"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "星はなんで輝いてるの",
        "雲はどうして空を泳ぐの",
        "人はなんで夢を描くの",
        "答えなんてないのかな"
      ]
    },
    {
      "section": "D1",
      "lyrics": [
        "いつかこんなちいさなうたは",
        "きみはきっとわすれちゃうけど",
        "ぼくはずっとおぼえているよ",
        "おとなになってもね"
      ]
    },
    {
      "section": "V3",
      "lyrics": [
        "今日はどんな話をしよう？",
        "君とどんな歌を歌おう？",
        "誰もまだ知らない花も"
      ]
    },
    {
      "section": "O1",
      "lyrics": [
        "ぜんぶ ぜんぶ ぜんぶ",
        "さがしにゆこう",
        "ぜんぶ ぜんぶ ぜんぶ",
